"use client";

import { motion } from "framer-motion";

const timeline = [
  {
    year: "2025 - Present",
    title: "AI Engineer",
    company: "L&T Technology Services (LTTS)",
    description:
      "Building enterprise AI solutions, RAG systems, Computer Vision applications, and manufacturing AI platforms.",
  },
  {
    year: "2021 - 2025",
    title: "Bachelor of Engineering",
    company: "Chandigarh University",
    description:
      "Computer Science & Engineering with focus on Software Engineering, Artificial Intelligence, Data Structures, Algorithms, and System Design.",
  },
];

export default function Experience() {
  return (
    <section
      id="experience"
      className="mx-auto min-h-[90vh] max-w-5xl px-6 py-24 transition-colors duration-300 lg:px-8"
    >
      {/* Section Header */}
      <motion.div
        initial={{ opacity: 0, y: 30 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true, amount: 0.2 }}
        transition={{ duration: 0.6 }}
        className="text-center"
      >
        <span className="inline-flex rounded-full bg-blue-100 px-4 py-2 text-sm font-semibold text-blue-700 dark:bg-blue-950/50 dark:text-blue-400">
          EXPERIENCE
        </span>

        <h2 className="mt-5 text-4xl font-black tracking-tight text-zinc-900 dark:text-white md:text-5xl">
          My Journey
        </h2>

        <p className="mx-auto mt-5 max-w-3xl text-base leading-8 text-zinc-600 dark:text-zinc-400 md:text-lg">
          A timeline of my education and professional experience.
        </p>
      </motion.div>

      {/* Timeline */}
      <div className="relative mt-14 border-l-2 border-blue-600 pl-8 md:pl-10">
        {timeline.map((item, index) => (
          <motion.div
            key={`${item.year}-${item.title}`}
            initial={{ opacity: 0, x: -30 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true, amount: 0.2 }}
            transition={{
              duration: 0.5,
              delay: index * 0.15,
            }}
            className="relative mb-12 last:mb-0"
          >
            {/* Timeline Dot */}
            <div className="absolute -left-[41px] top-1.5 h-5 w-5 rounded-full border-4 border-white bg-blue-600 dark:border-zinc-950" />

            {/* Content Card */}
            <div className="rounded-2xl border border-zinc-200 bg-white p-6 shadow-sm transition-all duration-300 hover:-translate-y-1 hover:shadow-lg dark:border-zinc-700 dark:bg-zinc-900">
              <p className="text-sm font-semibold text-blue-600 dark:text-blue-400">
                {item.year}
              </p>

              <h3 className="mt-2 text-xl font-bold text-zinc-900 dark:text-white md:text-2xl">
                {item.title}
              </h3>

              <h4 className="mt-1 text-base font-medium text-zinc-500 dark:text-zinc-400">
                {item.company}
              </h4>

              <p className="mt-4 text-base leading-7 text-zinc-600 dark:text-zinc-400">
                {item.description}
              </p>
            </div>
          </motion.div>
        ))}
      </div>
    </section>
  );
}