"use client";

import { motion } from "framer-motion";
import { FaExternalLinkAlt, FaGithub, FaPlay } from "react-icons/fa";

type Project = {
  title: string;
  category: string;
  description: string;
  technologies: string[];
  github: string;
  demo: string;
};

const projects: Project[] = [
  {
    title: "Smart Manufacturing Time Study AI",
    category: "Computer Vision",
    description:
      "AI-powered manufacturing activity recognition system that analyzes video, identifies worker activities and generates timeline-based productivity insights.",
    technologies: [
      "Python",
      "OpenCV",
      "PyTorch",
      "VideoMAE",
      "FastAPI",
    ],
    github: "#",
    demo: "#",
  },
  {
    title: "Enterprise RAG Document Assistant",
    category: "Generative AI",
    description:
      "Enterprise document intelligence platform using Retrieval-Augmented Generation to retrieve relevant knowledge and provide LLM-powered answers from technical documents.",
    technologies: [
      "Python",
      "LangChain",
      "LLM",
      "RAG",
      "Milvus",
      "Docker",
    ],
    github: "#",
    demo: "#",
  },
  {
    title: "AI Fault Investigation Assistant",
    category: "Enterprise AI",
    description:
      "AI-powered engineering assistant that uses RAG and LLMs to analyze machine failures and retrieve relevant information from engineering documentation.",
    technologies: [
      "Python",
      "RAG",
      "LLM",
      "FastAPI",
      "Vector DB",
    ],
    github: "#",
    demo: "#",
  },
  {
    title: "Natural Language → SQL Assistant",
    category: "LLM + Backend",
    description:
      "AI-powered assistant that converts natural language questions into SQL queries and retrieves structured answers from relational databases using an LLM-powered backend.",
    technologies: [
      "Python",
      "LLM",
      "SQL",
      "Spring Boot",
      "PostgreSQL",
      "REST API",
    ],
    github: "#",
    demo: "#",
  },
  {
    title: "AI Customer Support Assistant",
    category: "AI + Full Stack",
    description:
      "Intelligent customer support platform designed to understand user queries, retrieve relevant information and provide contextual AI-assisted responses.",
    technologies: [
      "Python",
      "LLM",
      "RAG",
      "Java",
      "Spring Boot",
      "React",
    ],
    github: "#",
    demo: "#",
  },
  {
    title: "AI Resume Analyzer",
    category: "Generative AI",
    description:
      "AI-powered resume analysis application that extracts candidate information, evaluates skills and provides structured insights using LLM-based processing.",
    technologies: [
      "Python",
      "LLM",
      "NLP",
      "React",
      "FastAPI",
    ],
    github: "#",
    demo: "#",
  },
  {
    title: "Invoice Intelligence System",
    category: "Document AI",
    description:
      "Intelligent document processing system designed to extract structured information from invoices and automate downstream business workflows.",
    technologies: [
      "Python",
      "OCR",
      "LLM",
      "FastAPI",
      "RAG",
    ],
    github: "#",
    demo: "#",
  },
  {
    title: "Electronic Store",
    category: "Java Full Stack",
    description:
      "Backend-focused electronic store application built with Spring Boot and secured REST APIs for managing users, products and application resources.",
    technologies: [
      "Java",
      "Spring Boot",
      "Spring Security",
      "JWT",
      "REST API",
      "SQL",
    ],
    github: "#",
    demo: "#",
  },
];

export default function Projects() {
  return (
    <section
      id="projects"
      className="relative overflow-hidden py-24 md:py-32"
    >
      <div className="mx-auto max-w-7xl px-6 lg:px-8">
        {/* Section Header */}
        <motion.div
          initial={{ opacity: 0, y: 40 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, amount: 0.2 }}
          transition={{ duration: 0.7 }}
          className="mx-auto max-w-3xl text-center"
        >
          <span className="inline-flex rounded-full border border-blue-200 bg-blue-50 px-4 py-1.5 text-sm font-semibold tracking-wide text-blue-700 dark:border-blue-900/60 dark:bg-blue-950/40 dark:text-blue-400">
            FEATURED PROJECTS
          </span>

          <h2 className="mt-5 text-4xl font-black tracking-tight text-zinc-900 dark:text-white md:text-5xl">
            Things I&apos;ve Built
          </h2>

          <p className="mx-auto mt-5 max-w-3xl text-base leading-8 text-zinc-600 dark:text-zinc-400 md:text-lg">
            Production-focused AI applications, backend systems and
            full-stack projects built around real engineering problems.
          </p>
        </motion.div>

        {/* Project Cards */}
        <div className="mt-14 grid gap-8 md:grid-cols-2 xl:grid-cols-3">
          {projects.map((project, index) => (
            <motion.article
              key={project.title}
              initial={{ opacity: 0, y: 40 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true, amount: 0.15 }}
              transition={{
                duration: 0.5,
                delay: index * 0.08,
              }}
              whileHover={{ y: -6 }}
              className="group flex h-full flex-col overflow-hidden rounded-3xl border border-zinc-200 bg-white shadow-sm transition-all duration-300 hover:shadow-xl dark:border-zinc-800 dark:bg-zinc-900"
            >
              {/* Project Preview */}
              <div className="relative flex h-52 items-center justify-center overflow-hidden bg-gradient-to-br from-blue-700 via-indigo-600 to-cyan-500">
                {/* Background decoration */}
                <div
                  aria-hidden="true"
                  className="absolute -right-16 -top-16 h-40 w-40 rounded-full bg-white/10 blur-2xl"
                />

                <div
                  aria-hidden="true"
                  className="absolute -bottom-20 -left-10 h-40 w-40 rounded-full bg-white/10 blur-2xl"
                />

                {/* Project Number */}
                <span
                  aria-hidden="true"
                  className="relative text-7xl font-black tracking-tight text-white/15"
                >
                  {String(index + 1).padStart(2, "0")}
                </span>

                {/* Category */}
                <span className="absolute left-5 top-5 rounded-full border border-white/20 bg-black/15 px-3 py-1.5 text-xs font-semibold text-white backdrop-blur-md">
                  {project.category}
                </span>

                {/* Video Preview Indicator */}
                <div
                  aria-hidden="true"
                  className="absolute bottom-5 right-5 flex h-10 w-10 items-center justify-center rounded-full border border-white/20 bg-white/10 text-white backdrop-blur-md transition-transform duration-300 group-hover:scale-110"
                >
                  <FaPlay className="ml-0.5 text-sm" />
                </div>
              </div>

              {/* Project Content */}
              <div className="flex flex-1 flex-col p-7">
                {/* Title + Description */}
                <div>
                  <h3 className="text-xl font-bold leading-tight text-zinc-900 dark:text-white md:text-2xl">
                    {project.title}
                  </h3>

                  <p className="mt-4 text-sm leading-7 text-zinc-600 dark:text-zinc-400 md:text-base">
                    {project.description}
                  </p>
                </div>

                {/* Technologies */}
                <div className="mt-6">
                  <p className="mb-3 text-xs font-semibold uppercase tracking-wider text-zinc-500 dark:text-zinc-500">
                    Technologies
                  </p>

                  <div className="flex flex-wrap gap-2">
                    {project.technologies.map((technology) => (
                      <span
                        key={technology}
                        className="rounded-full border border-zinc-200 bg-zinc-50 px-3 py-1.5 text-xs font-medium text-zinc-700 dark:border-zinc-700 dark:bg-zinc-800/80 dark:text-zinc-300"
                      >
                        {technology}
                      </span>
                    ))}
                  </div>
                </div>

                {/* Actions */}
                <div className="mt-auto flex flex-wrap gap-3 pt-7">
                  {/* GitHub */}
                  <a
                    href={project.github}
                    onClick={(event) => {
                      if (project.github === "#") {
                        event.preventDefault();
                      }
                    }}
                    aria-label={`GitHub repository for ${project.title}`}
                    aria-disabled={project.github === "#"}
                    className={`inline-flex items-center gap-2 rounded-xl border px-4 py-2.5 text-sm font-semibold transition ${
                      project.github === "#"
                        ? "cursor-not-allowed border-zinc-200 text-zinc-400 dark:border-zinc-800 dark:text-zinc-600"
                        : "border-zinc-300 text-zinc-800 hover:bg-zinc-100 dark:border-zinc-700 dark:text-zinc-200 dark:hover:bg-zinc-800"
                    }`}
                  >
                    <FaGithub aria-hidden="true" />
                    GitHub
                  </a>

                  {/* Watch Demo */}
                  <a
                    href={project.demo}
                    onClick={(event) => {
                      if (project.demo === "#") {
                        event.preventDefault();
                      }
                    }}
                    aria-label={`Watch demo for ${project.title}`}
                    aria-disabled={project.demo === "#"}
                    className={`inline-flex items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition ${
                      project.demo === "#"
                        ? "cursor-not-allowed bg-zinc-100 text-zinc-400 dark:bg-zinc-800 dark:text-zinc-600"
                        : "bg-blue-600 text-white hover:bg-blue-700"
                    }`}
                  >
                    <FaPlay aria-hidden="true" />
                    Watch Demo
                  </a>

                  {/* External Link Indicator */}
                  <span
                    aria-hidden="true"
                    className="ml-auto hidden items-center text-zinc-400 transition-transform duration-300 group-hover:translate-x-1 md:flex"
                  >
                    <FaExternalLinkAlt className="text-sm" />
                  </span>
                </div>
              </div>
            </motion.article>
          ))}
        </div>
      </div>
    </section>
  );
}